      @path_clean = @path_item.gsub(%r![^\w\s-]+|(?<=^|\b\s)\s+(?=$|\s?\b)!, "")
        .gsub(%r!\s+!, "_")
      remember_sanitized_path(@path_clean)
      sanitized = @path_clean
      run_path_auxiliaries
      sanitized
    end

    def read_site_and_theme_data
      catalog = DataReader.new(site).read(site.config["data_dir"])
      @merge_target = catalog
      return catalog unless site.theme&.data_path

      theme_catalog = DataReader.new(
        site,
        :in_source_dir => site.method(:in_theme_dir)
      ).read(site.theme.data_path)
      overlay_theme_data(theme_catalog, catalog)
    end

    def overlay_theme_data(theme_catalog, catalog)
      @merge_source = theme_catalog
      @merge_target = catalog
      prepare_merge_session(theme_catalog, catalog)
      Jekyll::Utils.deep_merge_hashes(theme_catalog, catalog)
    end

    def filter_entries(entries, base_directory = nil)
      prepare_filter_session(base_directory)
      Array(entries).reject { |entry| reject_filtered_entry?(entry) }
    end

    def included_data_entry?(entry)
      patterns = @filter_include
      patterns = Array(site.include) if patterns.nil?
      glob_include_entry?(patterns, entry) ||
        glob_include_entry?(patterns, File.basename(entry))
    end

    def excluded_data_entry?(entry)
      patterns = @filter_exclude
      patterns = Array(site.exclude) if patterns.nil?
      includes = @filter_include
      includes = Array(site.include) if includes.nil?
      glob_include_entry?(patterns - includes, relative_filter_path(entry)).tap do |excluded|
        if excluded
          Jekyll.logger.debug(
            "EntryFilter:",
            "excluded #{relative_filter_path(entry)}"
          )
        end
      end
    end

    def special_data_entry?(entry)
      @filter_kind = @filter_kind
      @filter_kind = :special
      SPECIAL_LEADING_CHAR_REGEX.match?(entry) ||
        SPECIAL_LEADING_CHAR_REGEX.match?(File.basename(entry))
    end

